-- =============================================================
-- FinanceHub — Master 60 Curated Books Seed Script
-- sql/master_60_books_library_seed.sql
-- Exactly 10 books per track across 6 tracks (Total: 60 books)
-- =============================================================

-- Ensure badge column exists
ALTER TABLE books ADD COLUMN IF NOT EXISTS badge TEXT;

INSERT INTO books (
  title, author, cover_url, description, key_takeaways, why_read, best_for,
  category, difficulty, amazon_url, free_pdf_url, is_free_legal, pages, year_published, badge
) VALUES
('The Psychology of Money', 'Morgan Housel', 'https://covers.openlibrary.org/b/isbn/9780857197689-L.jpg', 'Financial success is about behaviour, not intelligence. Housel uses 19 short stories to show how people think about money in ways that are often irrational but deeply human.', '["Wealth is what you do not spend \u2014 it is invisible optionality and freedom by definition.", "Room for error is the single most underappreciated protective force in personal finance.", "Getting rich and staying rich are two entirely different skills requiring different mindsets.", "Reasonable beats rational \u2014 a plan you can stick to beats a theoretically optimal one you abandon.", "Compounding works best when you do not interrupt it unnecessarily.", "Save without a specific goal \u2014 savings is your insurance hedge against life''s unpredictable surprises."]'::JSONB, 'The single most important finance book for anyone starting out. It reframes money decisions as human behaviour, not maths.', ARRAY['beginner', 'investor', 'professional'], 'personal-finance', 'easy', 'https://www.amazon.in/Psychology-Money-Morgan-Housel/dp/9390166268', NULL, FALSE, 256, 2020, 'Must Read'),
('Rich Dad Poor Dad', 'Robert T. Kiyosaki', 'https://covers.openlibrary.org/b/isbn/9781612680194-L.jpg', 'Contrasts the financial philosophies of two fathers — one highly educated but financially poor, one a dropout who became rich — to teach the difference between working for money vs making money work for you.', '["The rich do not work for money \u2014 money works for them.", "Financial literacy is more important than academic education for building durable wealth.", "Your house is a liability, not an asset, if it takes money out of your pocket every month.", "The rich acquire assets; the poor and middle class acquire liabilities that they think are assets.", "Taxes and inflation consistently erode the wealth of traditional salaried employees."]'::JSONB, 'The most-read personal finance book globally because it fundamentally transforms how people view income, liabilities, and assets.', ARRAY['beginner', 'entrepreneur'], 'personal-finance', 'easy', 'https://www.amazon.in/Rich-Dad-Poor-Middle-Anniversary/dp/1612681131', NULL, FALSE, 336, 1997, 'Global Bestseller'),
('Let''s Talk Money', 'Monika Halan', 'https://covers.openlibrary.org/b/isbn/9780008302825-L.jpg', 'India''s most practical personal finance book. Halan explains how to protect your money, grow it, and plan for your family''s future specifically in the Indian financial and regulatory context.', '["Secure adequate pure term life insurance (10-15x income) and comprehensive health insurance before investing a single rupee.", "A 3-bank-account money box system (Income, Spend, and Emergency) brings total financial clarity.", "Low-cost broad index mutual funds beat the vast majority of active mutual funds over 10+ years.", "Real estate is not universally a great investment when factoring illiquidity, registry taxes, and maintenance.", "Define your financial milestones first before selecting any financial product."]'::JSONB, 'The gold-standard personal finance playbook written specifically for Indian families and working professionals. Zero jargon.', ARRAY['beginner', 'professional'], 'personal-finance', 'easy', 'https://www.amazon.in/Lets-Talk-Money-Monika-Halan/dp/0008302820', NULL, FALSE, 240, 2018, '🇮🇳 Indian Context'),
('The Millionaire Next Door', 'Thomas J. Stanley & William D. Danko', 'https://covers.openlibrary.org/b/isbn/9781589795471-L.jpg', 'Based on a 20-year empirical study of real millionaires, this book reveals that wealth is accumulated through living far below one''s means, disciplined savings, and rejecting lavish consumer status symbols.', '["PAWs (Prodigious Accumulators of Wealth) allocate time and energy to budgeting and investing; UAWs consume high status.", "High income does not equal high wealth \u2014 accumulation efficiency is what creates financial freedom.", "Most millionaires drive modest, used vehicles and live in middle-class neighborhoods.", "Economic outpatient care: subsidizing adult children destroys their ability to build independent financial discipline."]'::JSONB, 'Destroys media myths about wealthy lifestyles and provides an empirical blueprint for genuine self-made net worth.', ARRAY['beginner', 'professional', 'wealth-builder'], 'personal-finance', 'easy', 'https://www.amazon.in/Millionaire-Next-Door-Surprising-Americas/dp/1589795474', NULL, FALSE, 258, 1996, 'Wealth Science'),
('Your Money or Your Life', 'Vicki Robin & Joe Dominguez', 'https://covers.openlibrary.org/b/isbn/9780143115762-L.jpg', 'The seminal foundation of the modern FIRE (Financial Independence, Retire Early) movement. Teaches you to quantify money as ''life energy'' traded for time.', '["Calculate your Real Hourly Wage after subtracting commuting, work attire, de-stressing, and unpaid preparation time.", "Evaluate every expenditure by asking: ''Does this bring proportional fulfillment for the life energy spent?''", "The Crossover Point: when investment income surpasses monthly living expenses, you reach complete life autonomy.", "Frugality is not deprivation; it is the practice of extracting maximum joy from every resource."]'::JSONB, 'The philosophical and mathematical foundation for anyone seeking financial independence and mindful consumption.', ARRAY['beginner', 'fire-seeker', 'professional'], 'personal-finance', 'medium', 'https://www.amazon.in/Your-Money-Life-Transforming-Relationship/dp/0143115766', NULL, FALSE, 368, 1992, 'FIRE Pioneer'),
('I Will Teach You To Be Rich', 'Ramit Sethi', 'https://covers.openlibrary.org/b/isbn/9780761147480-L.jpg', 'A pragmatic 6-week program on conscious spending, automated banking pipelines, credit card optimization, and high-impact salary negotiations.', '["Spend extravagantly on the things you love, and cut costs mercilessly on the things you don''t.", "The Automated Money Flow: set up direct debits that automatically route paychecks into savings, investing, and fixed bills.", "Focus on the ''Big Wins'' (salary negotiation, asset allocation, investment fees) instead of agonizing over $3 lattes.", "The 85% Solution: an automated, imperfect system in action beats an unexecuted 100% ideal system every time."]'::JSONB, 'Zero guilt, hyper-actionable modern personal finance that rejects boring frugality and champions automated wealth.', ARRAY['beginner', 'young-professional'], 'personal-finance', 'easy', 'https://www.amazon.in/Will-Teach-You-Rich-Second/dp/1523505745', NULL, FALSE, 352, 2009, 'Conscious Spending'),
('The Simple Path to Wealth', 'JL Collins', 'https://covers.openlibrary.org/b/isbn/9781533667922-L.jpg', 'Originating as letters from a father to his daughter, this book distills financial independence down to its simplest, most elegant components: debt avoidance and low-cost index funds.', '["''F-You Money'' provides the sovereign freedom to walk away from bad bosses, toxic jobs, and unwanted obligations.", "The stock market is a relentless wealth generator that always climbs over 20-year horizons despite volatile crashes.", "Complexity is an industry profit model designed to extract management fees from uninformed investors.", "Hold low-cost total market index funds and never panic sell during bear market dips."]'::JSONB, 'The clearest, most empowering guide to building passive wealth without needing complex spreadsheets or market timing.', ARRAY['beginner', 'investor'], 'personal-finance', 'easy', 'https://www.amazon.in/Simple-Path-Wealth-financial-independence/dp/1533667925', NULL, FALSE, 286, 2016, 'Bogleheads Bible'),
('Coffee Can Investing', 'Saurabh Mukherjea, Rakshit Ranjan & Pranab Uniyal', 'https://covers.openlibrary.org/b/isbn/9780670090419-L.jpg', 'Applies Robert Kirby''s Coffee Can philosophy to Indian capital markets: buy great companies with high ROCE (>15%) and double-digit revenue growth, and lock them away for 10+ years.', '["Indian market compounding relies on clean accounting, transparent governance, and unmatched brand pricing power.", "Portfolio churn and short-term capital gains taxes are the silent destroyers of Indian retail wealth.", "True monopolistic Indian franchises (Asian Paints, Pidilite, Titan) consistently trounce fixed deposits and gold.", "Never compromise on corporate governance quality regardless of cheap trailing valuations."]'::JSONB, 'The definitive institutional blueprint for picking long-term wealth compounders in the Indian stock market.', ARRAY['investor', 'intermediate'], 'personal-finance', 'medium', 'https://www.amazon.in/Coffee-Can-Investing-Stupendous-Wealth/dp/0670090417', NULL, FALSE, 248, 2018, '🇮🇳 Indian Compounding'),
('Die with Zero', 'Bill Perkins', 'https://covers.openlibrary.org/b/isbn/9780358099765-L.jpg', 'Argues that accumulating maximum money at death is an unforced life error. Wealth should be converted into fulfilling life experiences enjoyed at the biological ages where utility is highest.', '["Your biological capacity to extract joy from money declines sharply as physical vitality deteriorates with age.", "Memory Dividends: memories created through experiences pay emotional and psychological dividends for decades.", "Transfer wealth to children and causes when they are in their 20s and 30s when it carries the highest life utility.", "Time-bucket your life into 5-year intervals to schedule physical and travel ambitions before health limits them."]'::JSONB, 'A profound philosophical counterweight to mindless hoarding, teaching intentional wealth deployment for maximum life fulfillment.', ARRAY['professional', 'fire-seeker'], 'personal-finance', 'medium', 'https://www.amazon.in/Die-Zero-Getting-Your-Money/dp/0358099765', NULL, FALSE, 240, 2020, 'Life Optimization'),
('The Total Money Makeover', 'Dave Ramsey', 'https://covers.openlibrary.org/b/isbn/9781591451648-L.jpg', 'A battle-tested behavioral blueprint for eliminating consumer debt and establishing ironclad emergency reserves using the debt snowball method.', '["The Debt Snowball: list debts smallest to largest; attack the smallest balance first for psychological momentum.", "Build an emergency buffer of 3-6 months of basic expenses before deploying capital into speculative markets.", "High-interest revolving credit cards are dangerous financial landmines that destroy household savings.", "Living on a zero-based budget gives every single rupee an assigned role before the month begins."]'::JSONB, 'The definitive tactical playbook for escaping chronic debt and establishing financial stability.', ARRAY['beginner'], 'personal-finance', 'easy', 'https://www.amazon.in/Total-Money-Makeover-Financial-Fitness/dp/1591451644', NULL, FALSE, 272, 2003, 'Debt Destruction'),
('The Intelligent Investor', 'Benjamin Graham', 'https://covers.openlibrary.org/b/isbn/9780062312686-L.jpg', 'The definitive guide to value investing, written by Warren Buffett''s mentor. Teaches the principles of investing with a margin of safety, controlling emotions, and understanding market volatility.', '["The stock market is a voting machine in the short term, but a weighing machine in the long term.", "Margin of safety is the three most important words in investing.", "Mr. Market is your servant, not your guide.", "The investor''s chief problem \u2014 and even his worst enemy \u2014 is likely to be himself.", "Never buy a stock immediately after a substantial rise or sell one immediately after a substantial drop."]'::JSONB, 'Required reading for anyone who wants to invest in stocks rather than speculate. Dense but transformative.', ARRAY['investor', 'advanced'], 'investing', 'advanced', 'https://www.amazon.in/Intelligent-Investor-Benjamin-Graham/dp/0062312685', NULL, FALSE, 640, 1949, 'Value Classic'),
('One Up on Wall Street', 'Peter Lynch', 'https://covers.openlibrary.org/b/isbn/9780743200400-L.jpg', 'Lynch, one of the most successful fund managers in history (Fidelity Magellan), explains how ordinary retail investors can beat Wall Street professionals by investing in businesses they observe in everyday life.', '["Invest in what you understand \u2014 your everyday observations as a consumer are valuable research.", "Retail investors have an informational edge over Wall Street analysts if they use their eyes.", "The P/E ratio must be contextualized with earnings growth (PEG ratio).", "Never invest in any business model that you cannot illustrate simply with a crayon.", "Know why you own every stock in your portfolio \u2014 be able to explain it in 2 minutes."]'::JSONB, 'A practical guide to stock picking from history''s most celebrated fund manager. Highly accessible and engaging.', ARRAY['investor', 'intermediate'], 'investing', 'medium', 'https://www.amazon.in/One-Up-Wall-Street-Already/dp/0743200403', NULL, FALSE, 304, 1989, 'Stock Picking'),
('The Warren Buffett Way', 'Robert G. Hagstrom', 'https://covers.openlibrary.org/b/isbn/9781118503256-L.jpg', 'Deconstructs Warren Buffett''s investment playbook through his historic portfolio allocations (Coca-Cola, American Express, Geico), articulating his management, financial, and market tenets.', '["Only buy equity in businesses whose economic engines you thoroughly understand.", "Look for durable competitive advantages \u2014 economic moats that protect return on invested capital.", "Price is what you pay; intrinsic value is what you receive.", "Be fearful when others are greedy, and greedy only when others are fearful.", "Holding period: if you aren''t willing to own a stock for 10 years, do not even think about owning it for 10 minutes."]'::JSONB, 'The clearest, most structured breakdown of how Buffett evaluates balance sheets and competitive moats.', ARRAY['investor', 'advanced'], 'investing', 'medium', 'https://www.amazon.in/Warren-Buffett-Way-Robert-Hagstrom/dp/1118503252', NULL, FALSE, 320, 1994, 'Buffett Tenets'),
('A Random Walk Down Wall Street', 'Burton Malkiel', 'https://covers.openlibrary.org/b/isbn/9780393358384-L.jpg', 'The intellectual cornerstone of passive index investing. Princeton economist Burton Malkiel proves that short-term price movements follow a random walk and active stock pickers fail to beat the index net of fees.', '["Short-term stock prices behave like a random walk \u2014 technical chart patterns lack predictive power.", "Broad low-cost index funds consistently outperform the majority of active fund managers over 15+ years.", "Asset allocation and diversification are the only true ''free lunches'' in capital markets.", "The compound interest arithmetic heavily rewards minimizing expense ratios and starting as young as possible."]'::JSONB, 'The foundational academic and empirical evidence for why passive index investing is the highest-probability wealth strategy.', ARRAY['investor', 'beginner', 'professional'], 'investing', 'medium', 'https://www.amazon.in/Random-Walk-Down-Wall-Street/dp/0393358380', NULL, FALSE, 456, 1973, 'Index Pioneer'),
('Security Analysis', 'Benjamin Graham & David Dodd', 'https://covers.openlibrary.org/b/isbn/9780071592536-L.jpg', 'The 1934 bible of fundamental securities valuation. Established the rigorous mathematical discipline of financial statement analysis, fixed income evaluation, balance sheet liquidation value, and margin of safety.', '["An investment operation is one which, upon thorough analysis, promises safety of principal and an adequate return.", "A securities analyst must look beyond reported accounting earnings to calculate true normalized owner earnings.", "The margin of safety is essential to protect capital against unforeseen structural shifts and human analytical error.", "Distinguish rigorously between investment and speculation in every market environment."]'::JSONB, 'For professional and serious investors seeking the uncompromising intellectual foundation of value investing and credit analysis.', ARRAY['investor', 'advanced'], 'investing', 'advanced', 'https://www.amazon.in/Security-Analysis-Foreword-Buffett-Editions/dp/0071592539', NULL, FALSE, 725, 1934, 'The Bible of Value'),
('Common Stocks and Uncommon Profits', 'Philip A. Fisher', 'https://covers.openlibrary.org/b/isbn/9780471445500-L.jpg', 'The pioneer manual of growth stock investing. Introduced the famed ''Scuttlebutt'' method and 15 qualitative points to identify businesses with multi-decade compounding potential.', '["The Scuttlebutt Method: interview customers, competitors, vendors, and ex-employees to uncover operational reality.", "Look for companies with superior R&D productivity and marketing engines capable of expanding market share.", "A strong management team with high integrity and transparent investor relations is worth paying a valuation premium for.", "If the job has been done correctly when a common stock is purchased, the time to sell it is almost never."]'::JSONB, 'The primary qualitative influence on Warren Buffett (''I am 85% Graham and 15% Fisher''). Essential for growth investors.', ARRAY['investor', 'intermediate'], 'investing', 'medium', 'https://www.amazon.in/Common-Stocks-Uncommon-Profits-Writings/dp/0471445509', NULL, FALSE, 320, 1958, 'Growth Pioneer'),
('The Most Important Thing', 'Howard Marks', 'https://covers.openlibrary.org/b/isbn/9780231153621-L.jpg', 'Oaktree Capital co-founder Howard Marks details second-level thinking, market pendulum swings, risk control, and exploiting collective investor mania.', '["First-level thinking is simplistic and superficial; second-level thinking is deep, complex, and considers market expectations.", "Risk is not beta or volatility; risk is the probability of permanent capital loss.", "The market is a pendulum swinging endlessly between irrational euphoria and unwarranted depression.", "Superior investing comes not from buying high-quality assets, but from buying assets for less than they are worth."]'::JSONB, 'Warren Buffett famously noted: ''When I see memos from Howard Marks in my mail, they''re the first thing I open and read.''', ARRAY['investor', 'advanced'], 'investing', 'advanced', 'https://www.amazon.in/Most-Important-Thing-Thoughtful-Columbia/dp/0231153622', NULL, FALSE, 200, 2011, 'Institutional Wisdom'),
('Margin of Safety', 'Seth Klarman', 'https://covers.openlibrary.org/b/isbn/9780887305108-L.jpg', 'The legendary, out-of-print institutional value investing classic by Baupost Group''s Seth Klarman on navigating market fads and sourcing distressed mispricings.', '["Value investing requires immense psychological discipline to lag speculative momentum markets in exchange for ironclad downside safety.", "Holding cash is an active strategic investment decision that provides liquidity to buy distressed assets in panics.", "Institutional structural flaws (quarterly benchmarking, window dressing) create forced-selling bargains for patient capital.", "Never confuse a good story with a sound investment; always anchor on tangible cash flows and balance sheet liquidation values."]'::JSONB, 'Considered the Holy Grail of modern hedge fund value investing. Outlines uncompromising risk control.', ARRAY['investor', 'advanced'], 'investing', 'advanced', 'https://www.amazon.in/Margin-Safety-Risk-Averse-Strategies-Thoughtful/dp/0887305105', NULL, FALSE, 249, 1991, 'Hedge Fund Grail'),
('The Little Book of Common Sense Investing', 'John C. Bogle', 'https://covers.openlibrary.org/b/isbn/9781119404507-L.jpg', 'Vanguard founder Jack Bogle proves mathematically that index funds are the only vehicle guaranteeing your fair share of stock market compound returns.', '["The Relentless Rules of Humble Arithmetic: Gross Market Return minus Intermediary Friction Costs = Net Investor Return.", "Don''t look for the needle in the haystack; simply buy the whole haystack.", "Corporate dividend yields and earnings growth drive 100% of real multi-decade returns; speculative P/E changes wash out.", "Minimize broker turnover, advisory fees, and taxes to let compounding work uninhibited."]'::JSONB, 'The timeless mathematical case for why passive indexing wins. Endorsed by Warren Buffett as the best book for everyday investors.', ARRAY['investor', 'beginner'], 'investing', 'easy', 'https://www.amazon.in/Little-Book-Common-Sense-Investing/dp/1119404509', NULL, FALSE, 216, 2007, 'Index Revolution'),
('Diamonds in the Dust', 'Saurabh Mukherjea, Rakshit Ranjan & Nandita Rajhansa', 'https://covers.openlibrary.org/b/isbn/9780670094981-L.jpg', 'A forensic investing masterclass on Indian equities. How to identify accounting manipulation, analyze corporate moats, and build durable multi-bagger portfolios.', '["Over 50% of listed Indian companies manipulate accounting; rigorous forensic checks on cash flow vs. EBITDA are essential.", "Exemplary Indian businesses establish monopolistic moats through supply chain supremacy and proprietary distribution networks.", "High ROCE paired with heavy capital reinvestment generates exponential shareholder compounding over decades.", "Reject speculative cyclical turnarounds in favor of consistent, cash-generating franchise monopolies."]'::JSONB, 'The definitive modern forensic accounting guide for evaluating companies and avoiding corporate governance traps in India.', ARRAY['investor', 'intermediate'], 'investing', 'medium', 'https://www.amazon.in/Diamonds-Dust-Consistent-Wealth-Creation/dp/0670094986', NULL, FALSE, 288, 2021, '🇮🇳 Forensic Value'),
('Flash Boys', 'Michael Lewis', 'https://covers.openlibrary.org/b/isbn/9780393244663-L.jpg', 'Lewis exposes how High-Frequency Trading (HFT) algorithms and dark pools exploit microsecond latency advantages to front-run ordinary retail orders on modern electronic exchanges.', '["Modern electronic exchanges are wired with hidden complexities that favor algorithmic latency arbitrage.", "Microsecond speed is the primary weapon in modern order routing.", "Complexity in financial exchange architecture often benefits predatory insiders at the expense of retail investors.", "Market reform requires transparent matching engines and alignment of incentives."]'::JSONB, 'A thrilling, investigative dive into the physical infrastructure, fiber cables, and dark pools of Wall Street.', ARRAY['trader', 'investor', 'advanced'], 'trading-markets', 'medium', 'https://www.amazon.in/Flash-Boys-Michael-Lewis/dp/0393351599', NULL, FALSE, 320, 2014, 'Market Plumbing'),
('Reminiscences of a Stock Operator', 'Edwin Lefèvre', 'https://covers.openlibrary.org/b/isbn/9780471059776-L.jpg', 'The fictionalized biography of legendary speculator Jesse Livermore. Widely regarded as the most insightful book on market psychology, tape reading, and trading discipline ever written.', '["It was never my thinking that made the big money for me; it was always my sitting. Sitting tight on a winning trend.", "The market is never wrong; opinions of market participants frequently are.", "A trader must battle two dangerous human instincts: hope of a rebound in a loser, and fear of losing an unrealized winner.", "Never average down on a losing trade; add to positions only when the market confirms your thesis."]'::JSONB, 'The timeless bible of speculative trading. Traders report learning more about market psychology from Livermore than modern textbooks.', ARRAY['trader', 'intermediate'], 'trading-markets', 'medium', 'https://www.amazon.in/Reminiscences-Stock-Operator-Edwin-Lef%C3%A8vre/dp/0471059776', NULL, FALSE, 299, 1923, 'Trader''s Bible'),
('Market Wizards', 'Jack D. Schwager', 'https://covers.openlibrary.org/b/isbn/9781118273050-L.jpg', 'Interviews with legendary traders (Paul Tudor Jones, Bruce Kovner, Ed Seykota, Michael Marcus) revealing the universal rules of risk control and trading psychology.', '["Risk management is paramount: elite traders risk only 1% to 2% of total equity on any individual trade.", "Trading methodology must harmonize with your unique personality; trend-followers and mean-reverters can both excel.", "Ruthless loss-cutting: every master trader accepts losses as an unavoidable cost of operating an edge.", "Emotional equanimity: maintain the exact same mental balance whether winning big or absorbing consecutive losses."]'::JSONB, 'The ultimate masterclass in how real market professionals manage risk, size positions, and recover from drawdowns.', ARRAY['trader', 'intermediate'], 'trading-markets', 'medium', 'https://www.amazon.in/Market-Wizards-Interviews-Top-Traders/dp/1118273052', NULL, FALSE, 480, 1989, 'Legends Masterclass'),
('Technical Analysis of the Financial Markets', 'John J. Murphy', 'https://covers.openlibrary.org/b/isbn/9780735200661-L.jpg', 'The definitive reference manual used by Chartered Market Technicians (CMT). Exhaustive coverage of chart construction, support/resistance, oscillators, volume, and intermarket relationships.', '["Market action discounts everything: all fundamental economic news and rumors are immediately reflected in price.", "Prices move in persistent trends that remain in force until decisive reversal signatures are confirmed.", "Volume must confirm price action: an advance accompanied by diminishing volume warns of an imminent top.", "Intermarket analysis: currency, bond, commodity, and equity markets are linked in predictable macroeconomic feedback loops."]'::JSONB, 'The single most comprehensive, authoritative textbook on technical analysis in existence.', ARRAY['trader', 'advanced'], 'trading-markets', 'advanced', 'https://www.amazon.in/Technical-Analysis-Financial-Markets-Comprehensive/dp/0735200661', NULL, FALSE, 542, 1999, 'CMT Bible'),
('Trading in the Zone', 'Mark Douglas', 'https://covers.openlibrary.org/b/isbn/9780735201446-L.jpg', 'Unravels the psychological roots of trading mistakes. Teaches traders to think in pure probabilities, eliminate fear, and achieve flow-state execution.', '["Anything can happen on any given trade; an edge is simply a higher probability of one outcome over another.", "You do not need to know what will happen next in the market in order to make money consistently.", "Fully accept risk before pulling the trigger; if you harbor fear of loss, you will hesitate or sabotage execution.", "Consistency is a mental state: the market cannot hurt you if you take full responsibility for outcomes."]'::JSONB, 'Universally hailed as the #1 book on trading psychology. Solves the mental barriers between knowing charts and executing profitably.', ARRAY['trader', 'intermediate'], 'trading-markets', 'medium', 'https://www.amazon.in/Trading-Zone-Confidence-Discipline-Attitude/dp/0735201447', NULL, FALSE, 240, 2000, 'Trading Mindset'),
('Japanese Candlestick Charting Techniques', 'Steve Nison', 'https://covers.openlibrary.org/b/isbn/9780735201811-L.jpg', 'The foundational text that introduced Japanese candlesticks to Western finance. Explains how to read buyer/seller dominance using dojis, hammers, engulfing patterns, and morning stars.', '["The candlestick real body illustrates the core balance of power; long wicks indicate strong price rejection.", "Reversal patterns (Dojis, Hammers, Shooting Stars) require confirmation from subsequent candles and volume.", "Combine candlestick signals with Western technical tools (trendlines, moving averages) for maximum reliability.", "Candlestick charts provide visual clarity on market sentiment hours or days before traditional bar charts."]'::JSONB, 'The book that revolutionized Western charting. Mandatory reading for anyone trading price action on candlesticks.', ARRAY['trader', 'intermediate'], 'trading-markets', 'medium', 'https://www.amazon.in/Japanese-Candlestick-Charting-Techniques-Contemporary/dp/0735201811', NULL, FALSE, 320, 1991, 'Candlestick Origin'),
('How to Make Money in Stocks', 'William J. O''Neil', 'https://covers.openlibrary.org/b/isbn/9780071614139-L.jpg', 'Investor''s Business Daily founder William O''Neil outlines the CAN SLIM methodology, combining fundamental earnings acceleration with cup-with-handle chart breakouts.', '["The CAN SLIM formula: Current earnings, Annual growth, New product/service, Supply/demand, Leader, Institutional sponsorship, Market direction.", "Cut every single loss at a strict 7% to 8% stop-loss threshold without hesitation or second-guessing.", "Buy leading stocks breaking out of sound consolidation bases (cup-with-handle, flat base) into new all-time highs.", "Market direction (the ''M'' in CAN SLIM) determines the fate of 75% of individual stocks; never trade against market distribution days."]'::JSONB, 'The most successful hybrid methodology combining corporate fundamental earnings with technical breakout timing.', ARRAY['trader', 'investor'], 'trading-markets', 'medium', 'https://www.amazon.in/How-Make-Money-Stocks-Winning/dp/0071614133', NULL, FALSE, 464, 1988, 'CAN SLIM Method'),
('Way of the Turtle', 'Curtis M. Faith', 'https://covers.openlibrary.org/b/isbn/9780071486644-L.jpg', 'The insider account of the legendary 1983 Turtle Trading experiment: how Richard Dennis took novice non-traders and turned them into multi-million dollar systematic trend followers.', '["Systematic volatility position sizing: calibrate contracts using the Average True Range (ATR / N) to equalize risk across commodities.", "Donchian breakout channels: buy 20-day high breakouts and exit on 10-day opposite breakouts.", "Expect significant drawdowns: trend-following systems endure frequent small losses compensated by massive trend windfalls.", "Robotic consistency: discretionary tinkering during painful drawdowns destroys the statistical mathematical edge."]'::JSONB, 'The ultimate playbook for rule-based, systematic trend following and volatility position sizing.', ARRAY['trader', 'advanced'], 'trading-markets', 'advanced', 'https://www.amazon.in/Way-Turtle-Methods-Turned-Ordinary/dp/007148664X', NULL, FALSE, 304, 2007, 'Trend Following'),
('Trade Your Way to Financial Freedom', 'Van K. Tharp', 'https://covers.openlibrary.org/b/isbn/9780071478717-L.jpg', 'Dr. Van Tharp demonstrates that market entry techniques contribute less than 10% of trading success; position sizing algorithms and risk-of-ruin mathematics govern returns.', '["The concept of R-multiples: measure trade gains and losses as multiples of initial risk (1R) to evaluate real system efficiency.", "Expectancy calculation: mathematical proof that systems with a 35% win rate can generate fortunes with high reward-to-risk ratios.", "Position sizing is the only variable directly protecting accounts against catastrophic risk of ruin.", "Design exits tailored to your objectives: profit targets, trailing volatility stops, and time-based exits."]'::JSONB, 'The foundational mathematical manual on position sizing and statistical expectancy in trading systems.', ARRAY['trader', 'advanced'], 'trading-markets', 'advanced', 'https://www.amazon.in/Trade-Your-Way-Financial-Freedom/dp/007147871X', NULL, FALSE, 496, 1998, 'Position Sizing Math'),
('The New Trading for a Living', 'Dr. Alexander Elder', 'https://covers.openlibrary.org/b/isbn/9781118443927-L.jpg', 'Dr. Elder combines psychiatric insight with practical technical analysis, introducing the 2% and 6% risk rules and the Triple Screen multi-timeframe system.', '["The 3 M''s of trading: Mind (psychology), Method (chart analysis), and Money (risk management).", "The Triple Screen system: examine weekly charts for secular trend, daily charts for counter-trend entries, intra-day for precision timing.", "The 2% Rule: never risk more than 2% of total account equity on any single trade.", "The 6% Rule: halt trading for the remainder of the calendar month if total losses reach 6% of account value.", "Maintain a detailed trading journal with entry/exit screenshots and emotional state notes to build self-discipline."]'::JSONB, 'The most structured, well-rounded single-volume trading operating manual for active traders.', ARRAY['trader', 'intermediate'], 'trading-markets', 'medium', 'https://www.amazon.in/New-Trading-Living-Psychology-Management/dp/1118443926', NULL, FALSE, 304, 1993, 'Complete System'),
('Zero to One', 'Peter Thiel', 'https://covers.openlibrary.org/b/isbn/9780804139298-L.jpg', 'Notes on startups and how to build the future. Thiel argues that the next big innovation is not copying existing ideas but creating truly new ones — going from zero to one.', '["Competition is for losers \u2014 monopoly with high margins is the true engine of business profit.", "Every great business is built around a secret that others don''t see.", "The most contrarian thing is not to oppose the crowd but to think for yourself.", "A startup messed up at its foundation cannot be fixed later.", "Sales and distribution are as critical to success as the product itself."]'::JSONB, 'Essential for anyone building a business or evaluating high-growth early-stage equity investments.', ARRAY['founder', 'investor'], 'corporate-finance', 'medium', 'https://www.amazon.in/Zero-One-Notes-Startups-Future/dp/0804139296', NULL, FALSE, 224, 2014, 'Founders'),
('The Almanack of Naval Ravikant', 'Eric Jorgenson', 'https://covers.openlibrary.org/b/isbn/9781544514215-L.jpg', 'Compiled wisdom of Naval Ravikant on wealth, happiness, and building modern leverage. Covers how to build wealth without relying on luck — through code, media, capital, and labor.', '["Seek wealth, not money or status. Wealth is owning assets that earn while you sleep.", "Learn to sell, learn to build. If you can do both, you will be unstoppable.", "Specific knowledge cannot be taught in school \u2014 it is found by pursuing your genuine curiosity.", "Permissionless leverage (code and media) is the modern equalizer for wealth creation.", "Compound yourself \u2014 your compounding knowledge and reputation matter more than salary."]'::JSONB, 'Modern essential reading for builders and knowledge workers thinking about wealth creation in the internet era.', ARRAY['founder', 'entrepreneur', 'investor'], 'corporate-finance', 'easy', 'https://www.navalmanack.com/', 'https://www.navalmanack.com/', TRUE, 244, 2020, '100% Free Legal PDF'),
('The Lean Startup', 'Eric Ries', 'https://covers.openlibrary.org/b/isbn/9780307887894-L.jpg', 'The definitive blueprint for launching and financing new ventures under extreme uncertainty using validated learning, scientific experimentation, and the Build-Measure-Learn cycle.', '["The Build-Measure-Learn loop: ship the Minimum Viable Product (MVP) fast, measure truth, adapt quickly.", "Validated customer learning is infinitely more valuable than executing a 5-year business plan.", "Vanity metrics (pageviews, app downloads) deceive; actionable metrics reveal genuine customer value.", "The discipline to pivot or persevere based on real customer data rather than founder ego."]'::JSONB, 'Mandatory reading for founders and corporate capital allocators before deploying capital on new business ventures.', ARRAY['founder', 'entrepreneur'], 'corporate-finance', 'easy', 'https://www.amazon.in/Lean-Startup-Eric-Ries/dp/0670921602', NULL, FALSE, 336, 2011, 'Startups'),
('Shoe Dog', 'Phil Knight', 'https://covers.openlibrary.org/b/isbn/9781501135910-L.jpg', 'Nike founder Phil Knight''s candid memoir detailing the harrowing financial crises, import hurdles, bank credit rejections, and liquidity shortages that almost destroyed Nike before it became a $30B+ global empire.', '["Cash flow is the lifeblood of a growing business \u2014 rapid sales growth demands massive working capital.", "Revenue is vanity, profit is sanity, but cash in the bank is absolute reality.", "Perseverance through repeated near-bankruptcy events defines enduring company builders.", "Authentic corporate culture and relentless customer focus become unassailable balance sheet assets."]'::JSONB, 'The most honest, gripping memoir ever written on the raw financial pressure and cash flow terror of entrepreneurship.', ARRAY['founder', 'entrepreneur'], 'corporate-finance', 'easy', 'https://www.amazon.in/Shoe-Dog-Memoir-Creator-NIKE/dp/1471146723', NULL, FALSE, 400, 2016, 'Inspiring Memoir'),
('Good to Great', 'Jim Collins', 'https://covers.openlibrary.org/b/isbn/9780066620992-L.jpg', 'An empirical 5-year study identifying the management, cultural, and capital allocation frameworks that enabled good companies to achieve 15-year sustained market-beating returns.', '["Level 5 Leadership: personal humility paired with intense, uncompromising professional will.", "First Who, Then What: get the right talent on the bus and in the right seats before deciding where to drive.", "The Hedgehog Concept: focus at the intersection of passion, economic driver, and world-class capability.", "The Flywheel Effect: enduring greatness is built through cumulative, disciplined pushes in one direction."]'::JSONB, 'The gold-standard corporate research study on organizational excellence and long-term shareholder value creation.', ARRAY['founder', 'executive'], 'corporate-finance', 'medium', 'https://www.amazon.in/Good-Great-Some-Companies-Others/dp/0066620996', NULL, FALSE, 320, 2001, 'Management Science'),
('The Hard Thing About Hard Things', 'Ben Horowitz', 'https://covers.openlibrary.org/b/isbn/9780062273208-L.jpg', 'Andreessen Horowitz co-founder shares raw, unvarnished wisdom on managing cash burn, executive firings, layoffs, and existential company survival when there are no easy answers.', '["Peacetime CEO vs. Wartime CEO: peacetime focuses on expansion and culture; wartime fights existential runway extinction.", "The Struggle: every great leader experiences psychological terror, isolation, and near-catastrophic failures.", "Bad news must travel fast inside an organization to enable timely crisis intervention.", "Hire for strengths rather than lack of weaknesses; exceptional performers always have idiosyncratic rough edges."]'::JSONB, 'The definitive field manual for CEOs and founders navigating existential business crises and venture scaling.', ARRAY['founder', 'executive'], 'corporate-finance', 'advanced', 'https://www.amazon.in/Hard-Thing-About-Things-Building/dp/0062273205', NULL, FALSE, 304, 2014, 'Wartime CEO'),
('Damodaran on Valuation', 'Aswath Damodaran', 'https://covers.openlibrary.org/b/isbn/9780471751212-L.jpg', 'NYU Stern professor Damodaran outlines the rigorous mechanics of Discounted Cash Flow (DCF), relative multiples, cost of capital, and equity valuation.', '["Valuation is not about spreadsheets or accounting; it is about projecting cash flows discounted for uncertainty.", "Connect the story to the numbers: a credible valuation requires bridging operational narratives to financial models.", "Distinguish between Free Cash Flow to Firm (FCFF) and Free Cash Flow to Equity (FCFE) when evaluating leverage.", "Terminal value accounts for the majority of DCF value; stress-test perpetual growth assumptions relentlessly."]'::JSONB, 'Written by the ''Dean of Valuation''. The undisputed university textbook for investment bankers, analysts, and CFOs.', ARRAY['analyst', 'investor', 'advanced'], 'corporate-finance', 'advanced', 'https://www.amazon.in/Damodaran-Valuation-Security-Investment-Corporate/dp/0471751219', NULL, FALSE, 685, 2006, 'Valuation Bible'),
('Financial Shenanigans', 'Howard M. Schilit & Jeremy Perler', 'https://covers.openlibrary.org/b/isbn/9781260128826-L.jpg', 'The premier forensic accounting manual. Identifies 7 earnings manipulation tricks, 3 cash flow gimmicks, and key metric distortions used by corporate management.', '["Recognizing revenue prematurely: watch for surging unbilled accounts receivable far outpacing sales growth.", "Boosting income with one-time gains: reclassifying recurring operating costs into discontinued operations.", "Shifting current expenses to future periods: capitalizing routine operating expenses on the balance sheet.", "Cash flow manipulation: using aggressive working capital timing (stretching payables) to disguise operational bleed."]'::JSONB, 'The ultimate field guide to reading between the lines of audited financial statements and spotting fraud early.', ARRAY['analyst', 'investor', 'advanced'], 'corporate-finance', 'advanced', 'https://www.amazon.in/Financial-Shenanigans-Accounting-Gimmicks-Reports/dp/1260128828', NULL, FALSE, 352, 2018, 'Forensic Accounting'),
('7 Powers: The Foundations of Business Strategy', 'Hamilton Helmer', 'https://covers.openlibrary.org/b/isbn/9780998116310-L.jpg', 'Establishes the 7 persistent structural advantages that enable businesses to create enduring differential economic margins: Scale, Network, Counter-Positioning, Switching Costs, Branding, Cornered Resources, and Process Power.', '["Power is the set of conditions that creates persistent superior cash flows and pricing power.", "Counter-Positioning: a newcomer adopts a novel model that collateral damage prevents incumbents from adopting.", "Without at least one of the 7 Powers, operational excellence will be eroded by competitive replication.", "Statics vs. Dynamics: analyzing both the benefit of a power and the historical window required to seize it."]'::JSONB, 'Lauded by Silicon Valley venture capitalists and top equity analysts as the definitive modern framework for evaluating corporate moats.', ARRAY['founder', 'investor', 'advanced'], 'corporate-finance', 'advanced', 'https://www.amazon.in/Powers-Foundations-Business-Strategy-Hamilton/dp/0998116319', NULL, FALSE, 210, 2016, 'Moat Architecture'),
('Principles: Life and Work', 'Ray Dalio', 'https://covers.openlibrary.org/b/isbn/9781501124020-L.jpg', 'Bridgewater Associates founder shares the operating protocols, radical truth, and algorithmic decision systems that built the world''s most successful hedge fund.', '["Treat business as an algorithmic machine: when problems occur, diagnose which component of the machine failed.", "Idea Meritocracy: decisions should be determined by believability-weighted reasoning rather than seniority.", "Pain + Reflection = Progress: embracing harsh reality and learning from failure is the core driver of growth.", "Radical truth and radical transparency eliminate political friction and reveal organizational facts."]'::JSONB, 'A masterwork on engineering organizational systems, corporate culture, and systematic execution.', ARRAY['founder', 'executive'], 'corporate-finance', 'medium', 'https://www.amazon.in/Principles-Life-Work-Ray-Dalio/dp/1501124021', NULL, FALSE, 592, 2017, 'Systemic Thinking'),
('Thinking, Fast and Slow', 'Daniel Kahneman', 'https://covers.openlibrary.org/b/isbn/9780374275631-L.jpg', 'Nobel laureate Daniel Kahneman unpacks the human brain''s dual cognitive operating systems: intuitive, emotional System 1 and deliberative, logical System 2 — and why they distort financial decisions.', '["System 1 thinking creates predictable cognitive biases: overconfidence, anchoring, and loss aversion.", "Loss aversion: psychological pain of losing \u20b910,000 is twice as intense as the joy of winning \u20b910,000.", "The planning fallacy consistently tricks investors into underestimating risk, costs, and timeline.", "Availability heuristic causes us to overweight recent dramatic news over long-term base rates.", "Hindsight bias tricks us into believing market crashes were obvious in advance."]'::JSONB, 'Understanding your internal psychological biases is as vital as analyzing cash flows. Essential for every market participant.', ARRAY['investor', 'professional'], 'behavioral-finance', 'advanced', 'https://www.amazon.in/Thinking-Fast-Slow-Daniel-Kahneman/dp/0141033576', NULL, FALSE, 512, 2011, 'Nobel Prize'),
('Poor Charlie''s Almanack', 'Charles T. Munger', 'https://covers.openlibrary.org/b/isbn/9781578645015-L.jpg', 'The wit, wisdom, and multidisciplinary mental models of Berkshire Hathaway''s legendary Vice Chairman, Charlie Munger — spanning psychology, mathematics, physics, and investing.', '["Invert, always invert: to solve hard problems, analyze what would guarantee catastrophe and avoid it.", "Build a latticework of mental models from primary disciplines rather than relying on a single specialization.", "The big money is not in buying or selling, but in waiting for extreme mispricings.", "Avoid psychological misjudgments: commitment bias, authority bias, and incentive-caused bias.", "Consistently attempting to be ''not stupid'' yields superior long-term results than trying to be very brilliant."]'::JSONB, 'The pinnacle of intellectual rigor in capital allocation. Munger''s mental models apply universally across life and wealth.', ARRAY['investor', 'founder', 'advanced'], 'behavioral-finance', 'advanced', 'https://www.amazon.in/Poor-Charlies-Almanack-Charles-Munger/dp/1578645018', NULL, FALSE, 548, 2005, 'Mental Models'),
('Misbehaving', 'Richard H. Thaler', 'https://covers.openlibrary.org/b/isbn/9780393080940-L.jpg', 'Nobel laureate Richard Thaler chronicles the battle to replace traditional, idealized economic models of rational ''Econs'' with real, emotional ''Humans'' who make systematic errors.', '["Mental Accounting: humans treat money in artificial psychological buckets (winnings vs. savings) despite currency being fungible.", "The Endowment Effect: people demand significantly more to give up an asset they own than they would pay to acquire it.", "Sunk Cost Fallacy: throwing good money after bad simply to justify prior emotional or financial investments.", "Fairness matters: consumers and investors will actively punish perceived unfairness even at direct economic cost to themselves."]'::JSONB, 'The entertaining and authoritative history of behavioral economics written by its founding pioneer.', ARRAY['investor', 'economist'], 'behavioral-finance', 'medium', 'https://www.amazon.in/Misbehaving-Making-Behavioral-Economics-Richard/dp/0393080943', NULL, FALSE, 432, 2015, 'Behavioral Economics'),
('Fooled by Randomness', 'Nassim Nicholas Taleb', 'https://covers.openlibrary.org/b/isbn/9780812975215-L.jpg', 'Explores how human cognitive machinery confuses luck with skill in markets, blinded by survivorship bias, retrospective rationalization, and nonlinear distributions.', '["Alternative Histories: never judge a decision solely by its result; evaluate all alternate possibilities that could have unfolded.", "Survivorship Bias: markets celebrate victorious traders while burying the thousands who blew up using identical risk profiles.", "Mild success can be generated by labor and talent; extreme outsized success is almost always governed by randomness and variance.", "Skewness: an investment with a 99% probability of profit can still be catastrophic if the 1% loss wipes out total equity."]'::JSONB, 'An essential antidote to overconfidence and hubris in trading, hedge fund selection, and financial forecasting.', ARRAY['trader', 'investor', 'advanced'], 'behavioral-finance', 'advanced', 'https://www.amazon.in/Fooled-Randomness-Hidden-Markets-Incerto/dp/0812975219', NULL, FALSE, 368, 2001, 'Probability & Luck'),
('The Black Swan', 'Nassim Nicholas Taleb', 'https://covers.openlibrary.org/b/isbn/9781400063512-L.jpg', 'Focuses on extreme, high-impact, rare events (Black Swans) that dictate market history and portfolio outcomes, and why standard financial risk models fail to anticipate them.', '["Mediocristan vs. Extremistan: capital markets operate in Extremistan where single outlier events dominate aggregate history.", "The Ludic Fallacy: real-world risk cannot be modeled using the neat, controlled parameters of casino games or Gaussian curves.", "Epistemic Arrogance: financial institutions consistently overestimate what they know and underestimate risk of ruin.", "Antifragility: build portfolios with asymmetrical upside (convex payoffs) that benefit from unexpected market shocks."]'::JSONB, 'One of the most influential economic treatises of the 21st century. Revolutionized modern institutional risk management.', ARRAY['investor', 'risk-manager', 'advanced'], 'behavioral-finance', 'advanced', 'https://www.amazon.in/Black-Swan-Impact-Highly-Improbable/dp/0141034599', NULL, FALSE, 400, 2007, 'Fat Tails'),
('Nudge', 'Richard H. Thaler & Cass R. Sunstein', 'https://covers.openlibrary.org/b/isbn/9780143115267-L.jpg', 'How deliberate design in choice architecture can steer human behavior toward dramatically better financial, savings, and investment decisions without coercion.', '["The Power of Defaults: auto-enrolling workers into retirement savings plans skyrockets savings rates compared to opt-in systems.", "''Save More Tomorrow'': committing to allocate a portion of future salary raises prevents the psychological pain of cutting current take-home pay.", "Incentives and transparent feedback loops dramatically curb impulsive financial behavior.", "Libertarian Paternalism: guiding choices toward long-term welfare while preserving complete freedom to opt out."]'::JSONB, 'The foundational blueprint for how behavioral design can automate savings, prevent mistakes, and optimize societal wealth.', ARRAY['beginner', 'designer'], 'behavioral-finance', 'easy', 'https://www.amazon.in/Nudge-Improving-Decisions-Health-Happiness/dp/014311526X', NULL, FALSE, 384, 2008, 'Choice Architecture'),
('Predictably Irrational', 'Dan Ariely', 'https://covers.openlibrary.org/b/isbn/9780061353239-L.jpg', 'MIT behavioral economist Dan Ariely demonstrates through empirical experiments that human irrationality is not random; it is systematic and predictably repeated.', '["The Zero Price Effect: ''Free'' goods trigger an irrational emotional charge leading people to make counterproductive financial trade-offs.", "Anchoring: arbitrary numbers presented during first impressions permanently distort value perceptions.", "Social Norms vs. Market Norms: introducing cash into relationships governed by social duty erodes community cooperation.", "The Cost of Social Comparison: relative positioning drives financial misery far more than absolute purchasing power."]'::JSONB, 'A fascinating, accessible breakdown of how our irrational brains make everyday economic trade-offs.', ARRAY['beginner', 'general'], 'behavioral-finance', 'easy', 'https://www.amazon.in/Predictably-Irrational-Hidden-Forces-Decisions/dp/0061353248', NULL, FALSE, 384, 2008, 'Cognitive Quirks'),
('Superforecasting', 'Philip E. Tetlock & Dan Gardner', 'https://covers.openlibrary.org/b/isbn/9780804136693-L.jpg', 'Findings from the Good Judgment Project: how ordinary amateur forecasters consistently outperformed CIA intelligence analysts and Wall Street economists through cognitive humility and Bayesian updating.', '["Foxes beat Hedgehogs: thinkers with multidisciplinary mental models outperform dogmatic experts who view history through one grand ideology.", "Break complex questions into sub-problems (Fermi estimation) and start with outside statistical base rates before adjusting for unique facts.", "Bayesian updating: update probability estimates in small, granular increments as new data emerges.", "Treat beliefs as testable hypotheses rather than sacred personal dogmas to defend."]'::JSONB, 'The ultimate scientific manual for building calibrated probabilistic forecasting skills in capital markets.', ARRAY['analyst', 'investor'], 'behavioral-finance', 'medium', 'https://www.amazon.in/Superforecasting-Science-Prediction-Philip-Tetlock/dp/0804136696', NULL, FALSE, 352, 2015, 'Predictive Rigor'),
('Against the Gods: The Remarkable Story of Risk', 'Peter L. Bernstein', 'https://covers.openlibrary.org/b/isbn/9780471295631-L.jpg', 'The sweeping 300-year history of how humanity transformed risk from divine destiny into a quantifiable science of probability, game theory, and portfolio insurance.', '["The mastery of risk is the foundational intellectual leap separating the modern world from ancient fatalism.", "Probability pioneers (Pascal, Fermat, Bernoulli, Bayes) converted uncertainty into measurable mathematics.", "Diversification and hedging are mathematical mechanisms that preserve human enterprise across unpredictable futures.", "Mathematical models can never fully tame the irreducible irrationality of human greed and panic."]'::JSONB, 'The definitive philosophical and historical foundation of risk management across financial markets.', ARRAY['investor', 'historian', 'advanced'], 'behavioral-finance', 'advanced', 'https://www.amazon.in/Against-Gods-Remarkable-Story-Risk/dp/0471295639', NULL, FALSE, 400, 1996, 'History of Risk'),
('Seeking Wisdom: From Darwin to Munger', 'Peter Bevelin', 'https://covers.openlibrary.org/b/isbn/9781578644285-L.jpg', 'A comprehensive distillation of human cognitive errors and multidisciplinary mental models synthesized from evolutionary biology, physics, and Charlie Munger''s speeches.', '["A structured catalog of 28 core psychological misjudgments: incentive-caused bias, authority bias, social proof, commitment consistency.", "The power of critical mass, feedback loops, and compound interest in nature, business, and capital allocation.", "Checklist discipline: using formal checklists before allocating capital prevents catastrophic unforced errors.", "Understand reality as an interconnected biological ecosystem rather than isolated academic silos."]'::JSONB, 'The most exhaustive, practical encyclopedia of mental models and psychological errors ever compiled for serious investors.', ARRAY['investor', 'thinker', 'advanced'], 'behavioral-finance', 'advanced', 'https://www.amazon.in/Seeking-Wisdom-Darwin-Munger-3rd/dp/1578644483', NULL, FALSE, 328, 2003, 'Multidisciplinary Wisdom'),
('Principles for Navigating Big Debt Crises', 'Ray Dalio', 'https://covers.openlibrary.org/b/isbn/9781982113636-L.jpg', 'Ray Dalio outlines the mechanics of the 5-8 year short-term debt cycle and the 75-year long-term debt cycle, explaining inflationary vs deflationary deleveragings.', '["One man''s spending is another man''s income: when credit expands, spending increases; when credit contracts, economic activity plunges.", "A ''Beautiful Deleveraging'' balances austerity, debt restructuring, wealth redistribution, and central bank debt monetization.", "Depressions occur when debt service payments exceed borrowers'' capacity and central banks hit the zero lower bound.", "Studying historical macro crises (Weimar Germany, 1929 US, 2008 GFC) reveals identical causal templates."]'::JSONB, 'The premier institutional manual for understanding macroeconomic debt cycles, central bank liquidity, and systemic crises.', ARRAY['investor', 'macro-analyst', 'advanced'], 'crypto-defi', 'advanced', 'https://www.amazon.in/Principles-Navigating-Big-Debt-Crises/dp/1982113634', NULL, FALSE, 450, 2018, 'Macro Mechanics'),
('The Bitcoin Standard', 'Saifedean Ammous', 'https://covers.openlibrary.org/b/isbn/9781119473862-L.jpg', 'Traces the monetary history of civilizations (from Rai stones and seashells to gold and fiat) and argues that Bitcoin represents the first mathematically scarce hard monetary protocol.', '["Stock-to-Flow Ratio: sound money requires a high existing stock and low new flow that cannot be diluted by authorities.", "Time Preference: hard money lowers societal time preference, encouraging long-term capital accumulation; fiat debasement encourages debt and instant gratification.", "Government control of money allows monetization of warfare and unchecked sovereign deficit spending.", "Bitcoin as immutable digital gold: absolute 21-million programmatic scarcity enforced by decentralized consensus."]'::JSONB, 'The definitive economic argument for Bitcoin from an Austrian monetary economics framework.', ARRAY['crypto-allocator', 'intermediate'], 'crypto-defi', 'medium', 'https://www.amazon.in/Bitcoin-Standard-Decentralized-Alternative-Central/dp/1119473861', NULL, FALSE, 304, 2018, 'Austrian Economics'),
('Lords of Finance', 'Liaquat Ahamed', 'https://covers.openlibrary.org/b/isbn/9781594202001-L.jpg', 'Pulitzer Prize-winning account of the four central bankers of Britain, France, Germany, and the US whose rigid adherence to the gold standard triggered the Great Depression.', '["Rigid, dogmatic commitment to obsolete monetary standards (the pre-WWI gold parity) turned a recession into global catastrophe.", "Competitive devaluations and beggar-thy-neighbor protectionism destroy international trade and ignite geopolitical instability.", "Central bankers are vulnerable to intellectual arrogance and peer group groupthink during systemic panics.", "Liquidity injections must be coordinated internationally during global sovereign banking collapses."]'::JSONB, 'A breathtaking financial history that won the Pulitzer Prize. Essential for understanding modern central banking policy.', ARRAY['macro-analyst', 'historian', 'advanced'], 'crypto-defi', 'advanced', 'https://www.amazon.in/Lords-Finance-Bankers-Broke-World/dp/0143118060', NULL, FALSE, 564, 2009, 'Pulitzer Prize'),
('The Alchemy of Finance', 'George Soros', 'https://covers.openlibrary.org/b/isbn/9780471042068-L.jpg', 'Legendary hedge fund investor George Soros details his Theory of Reflexivity: market participants'' biased perceptions actively alter the fundamental reality they are observing.', '["The Theory of Reflexivity: markets are never in equilibrium; two-way feedback loops between prevailing bias and underlying reality create asset bubbles.", "Boom-Bust Sequences: reflexivity triggers virtuous self-reinforcing credit expansions followed by catastrophic liquidity reversals.", "Testing hypotheses with capital: Soros treats every macro investment as a real-time scientific experiment with predefined exit criteria.", "Sovereign currency pegs are inherently unstable when fiscal realities diverge from exchange rate mandates."]'::JSONB, 'The philosophical manual of history''s most celebrated macro speculator (''the man who broke the Bank of England'').', ARRAY['trader', 'macro-investor', 'advanced'], 'crypto-defi', 'advanced', 'https://www.amazon.in/Alchemy-Finance-Reading-Mind-Market/dp/0471042064', NULL, FALSE, 416, 1987, 'Reflexivity Theory'),
('The Price of Tomorrow', 'Jeff Booth', 'https://covers.openlibrary.org/b/isbn/9781999257408-L.jpg', 'Examines why exponential technological progress is inherently deflationary, and why central banks'' attempts to force inflation through debt creation fuel extreme inequality and systemic collapse.', '["Technology is exponentially deflationary: automation, AI, and software continuously drive the marginal cost of production toward zero.", "Central banks fighting natural technology deflation through massive credit expansion inflate asset bubbles and erode wages.", "A structural divergence exists between an inflationary debt monetary architecture and an exponential deflationary technology world.", "Embracing natural deflation allows technological productivity gains to be distributed broadly to all citizens as reduced living costs."]'::JSONB, 'A profound exploration of technology, macroeconomic policy, and why sound digital currency is inevitable in the AI age.', ARRAY['tech-investor', 'macro-thinker'], 'crypto-defi', 'medium', 'https://www.amazon.in/Price-Tomorrow-Deflation-Abundant-Future/dp/1999257405', NULL, FALSE, 240, 2020, 'Exponential Tech'),
('Currency Wars', 'James Rickards', 'https://covers.openlibrary.org/b/isbn/9781591844495-L.jpg', 'Traces the history of competitive exchange rate devaluations from Currency War I (1921-1936) through modern central bank quantitative easing and dollar weaponization.', '["Currency wars occur when sovereign nations engage in competitive devaluations to steal economic growth from trading partners.", "Devaluing currency is an export of deflation and unemployment that invites retaliatory trade tariffs and geopolitical tension.", "The US Dollar''s exorbitant privilege as global reserve currency faces long-term structural threats from alternative settlement networks.", "Hard tangible assets (gold, scarce resources) serve as ultimate monetary shields during sovereign currency debasement."]'::JSONB, 'A masterclass in geopolitical finance, foreign exchange dynamics, and macro sovereign risk.', ARRAY['forex-trader', 'macro-analyst'], 'crypto-defi', 'medium', 'https://www.amazon.in/Currency-Wars-Making-Global-Crisis/dp/1591845564', NULL, FALSE, 320, 2011, 'Geopolitics & FX'),
('When Genius Failed', 'Roger Lowenstein', 'https://covers.openlibrary.org/b/isbn/9780375758256-L.jpg', 'Chronicles the dramatic rise and catastrophic collapse of hedge fund Long-Term Capital Management (LTCM), where Nobel laureates used 100:1 leverage on bond arbitrage models that imploded in 1998.', '["Leverage destroys genius: mathematical models that function in 99% of normal market conditions result in total ruin in a 6-sigma shock.", "Liquidity is a coward: when panics occur, liquidity in arbitrage spreads completely evaporates.", "Overreliance on historical correlations: correlations across disparate asset classes converge to 1.0 during a global crisis.", "Hubris and mathematical overconfidence lead institutional allocators to underestimate tail risk."]'::JSONB, 'The definitive case study on why excessive leverage and quantitative overconfidence lead to sudden catastrophic blowups.', ARRAY['quant', 'trader', 'advanced'], 'crypto-defi', 'advanced', 'https://www.amazon.in/When-Genius-Failed-Long-Term-Management/dp/0375758259', NULL, FALSE, 288, 2000, 'Leverage Catastrophe'),
('Mastering Bitcoin', 'Andreas M. Antonopoulos', 'https://covers.openlibrary.org/b/isbn/9781491954386-L.jpg', 'The technical and cryptographic bible of peer-to-peer digital cash. Unpacks elliptic curve cryptography, UTXO transaction verification, proof-of-work consensus, and the blockchain protocol.', '["Decentralized trust: replacing trusted human intermediaries with mathematically verifiable cryptographic proof.", "The UTXO (Unspent Transaction Output) model prevents double-spending without needing a central ledger authority.", "Proof-of-work bridges physical thermodynamic energy expenditure to digital monetary security.", "Private keys confer sovereign custody: ''Not your keys, not your coins'' is an architectural truth."]'::JSONB, 'The definitive technical textbook for developers, fintech engineers, and serious investors seeking true mechanical comprehension of blockchain.', ARRAY['developer', 'crypto-allocator', 'advanced'], 'crypto-defi', 'advanced', 'https://www.amazon.in/Mastering-Bitcoin-Programming-Open-Blockchain/dp/1491954388', NULL, FALSE, 416, 2014, 'Blockchain Engineering'),
('Boomerang', 'Michael Lewis', 'https://covers.openlibrary.org/b/isbn/9780393081817-L.jpg', 'A dark, comedic journey across the sovereign debt ruins of Iceland, Greece, Ireland, and Germany following the 2008 subprime contagion, revealing how cheap credit intoxicated entire nations.', '["Unlimited cheap credit amplifies the unique cultural and psychological vices of every society that consumes it.", "Sovereign governments nationalized private banking debts, transforming Wall Street insolvency into European sovereign debt crises.", "Hidden public sector balance sheet liabilities and corrupt municipal pension accounting distort fiscal health.", "The European monetary union created a fatal mismatch: unified monetary policy with fragmented sovereign fiscal budgets."]'::JSONB, 'Gripping, razor-sharp narrative journalism on how sovereign debt bubbles infect nation-states.', ARRAY['general', 'investor'], 'crypto-defi', 'medium', 'https://www.amazon.in/Boomerang-Travels-New-Third-World/dp/0393343448', NULL, FALSE, 224, 2011, 'Sovereign Debt'),
('The New Lombard Street', 'Perry Mehrling', 'https://covers.openlibrary.org/b/isbn/9780691143989-L.jpg', 'Columbia professor Perry Mehrling introduces the ''Money View'': decoding modern financial plumbing through shadow banking balance sheets, repo markets, and liquidity dealers.', '["The Money View: economics focuses on value, finance focuses on cash flow, but the Money View focuses on liquidity and survival constraints.", "Shadow banking is market-based credit where securities dealers backstop liquidity through collateralized repo transactions.", "The Federal Reserve evolved from a traditional ''Lender of Last Resort'' into the ''Dealer of Last Resort'' backstopping global asset markets.", "Payment settlements require hierarchy: banks settle reserves with the central bank; shadow banks settle collateral with dealers."]'::JSONB, 'The most sophisticated modern conceptual framework for understanding how global dollar liquidity and repo markets actually function.', ARRAY['macro-analyst', 'fixed-income', 'advanced'], 'crypto-defi', 'advanced', 'https://www.amazon.in/New-Lombard-Street-Dealer-Resort/dp/069114398X', NULL, FALSE, 192, 2011, 'Money View')

ON CONFLICT (title, author) DO UPDATE SET
  cover_url = COALESCE(EXCLUDED.cover_url, books.cover_url),
  description = EXCLUDED.description,
  key_takeaways = EXCLUDED.key_takeaways,
  why_read = EXCLUDED.why_read,
  best_for = EXCLUDED.best_for,
